#include <bits/stdc++.h>
using namespace std;

using db = double;
using ll = long long;
using ld = long double;
using ui = unsigned int;
using ull = unsigned long long;

using pdd = pair<db, db>;
using pdl = pair<db, ld>;
using pld = pair<ld, db>;
using ldp = pair<ld, ld>;

using pll = pair<ll, ll>;
using pil = pair<int, ll>;
using pli = pair<ll, int>;
using pii = pair<int, int>;

#define f first
#define s second
#define en end()
#define bg begin()
#define rev reverse
#define mp make_pair
#define pb push_back

#define y1 y1234567890
#define um unordered_map

#define all(x) x.bg, x.en
#define sz(x) (int)x.size()
#define len(x) (int)strlen(x)

#define sqr(x) ((x + 0ll) * (x))
#define sqrd(x) ((x + 0.0) * (x))

#define forn(i, n) for (int i = 1; i <= n; i++)

const ll inf = (ll)1e18;
const ll mod = (ll)1e9 + 7;

const db eps = (db)1e-9;
const db pi = acos(-1.0);

const int dx[] = {0, 0, 1, 0, -1};
const int dy[] = {0, 1, 0, -1, 0};

const int N = (1 << 20);

ll bp(ll x, ll y){
    ll z = 1;
    while(y){
        if(y & 1)
            z = z * x % mod;
        x = x * x % mod;
        y >>= 1;    
    }
    return z;
}

ll ans, n, p[6][6], F[N], nump, m[N];
vector <pair <int, int> > E;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for(int i = 0; i < n; ++i)
        for(int j = 0; j < n; ++j){
            cin >> p[i][j];
            p[i][j] = p[i][j] * bp(100, mod - 2) % mod; 
        }

    for(int i = n; i < 6; ++i)
        for(int j = n; j < 6; ++j)
            p[i][j] = 1;

    for(int i = 0; i < 6; ++i)
        for(int j = 0; j < 3; ++j)
            E.emplace_back(i, j);

    for(int i = 0; i < 6; ++i)
        for(int j = i + 1; j < 6; ++j)
            for(int k = j + 1; k < 6; ++k){
                vector <int> v;
                v.pb(i);
                v.pb(j);
                v.pb(k);
                do{
                    int mask1 = ((1 << (v[0] * 3)) ^ (1 << (v[1] * 3 + 1)) ^ (1 << (v[2] * 3 + 2)));
                    for(int mask = 0; mask < (1 << 18); ++mask)
                        if((mask & mask1) == mask1)
                            m[mask] |= (1 << nump);
                }while(next_permutation(v.begin(), v.end()));    
                nump++;
            }        

    for(int mask = 0; mask < (1 << 18); ++mask){
        ll v = 1;
        for(int i = 0; i < 18; ++i){
            if((mask >> i) & 1)
                v = v * p[E[i].f][E[i].s] % mod;
            else v = v * ((1 - p[E[i].f][E[i].s] + mod) % mod) % mod;
        }
        F[m[mask]] += v;
        if(F[m[mask]] >= mod)
            F[m[mask]] -= mod;
    }

    for(int i = 0; i < 20; ++i)
        for(int mask = 0; mask < (1 << 20); ++mask)
            if(mask & (1<<i))
                F[mask] = (F[mask] + F[mask ^ (1 << i)]) % mod;

    for(int i = 0; i < (1 << 18); ++i)
        m[i] = 0;

    nump = 0;

    for(int i = 0; i < 6; ++i)
        for(int j = i + 1; j < 6; ++j)
            for(int k = j + 1; k < 6; ++k){
                vector <int> v;
                for(int ii = 0; ii < 6; ++ii)
                    if(ii != i && ii != j && ii != k)
                        v.pb(ii);
                do{
                    int mask1 = ((1 << (v[0] * 3)) ^ (1 << (v[1] * 3 + 1)) ^ (1 << (v[2] * 3 + 2)));
                    for(int mask = 0; mask < (1 << 18); ++mask)
                        if((mask & mask1) == mask1)
                            m[mask] |= (1 << nump);
                }while(next_permutation(v.begin(), v.end()));    
                nump++;
            }

    E.clear();
    for(int i = 0; i < 6; ++i)
        for(int j = 3; j < 6; ++j)
            E.emplace_back(i, j);

    for(int mask = 0; mask < (1 << 18); ++mask){
        ll v = 1;
        for(int i = 0; i < 18; ++i){
            if((mask >> i) & 1)
                v = v * p[E[i].f][E[i].s] % mod;
            else v = v * ((1 - p[E[i].f][E[i].s] + mod) % mod) % mod;
        }
        ans = (ans + v * ((1 - F[((1 << 20) - 1) ^ m[mask]]  + mod) % mod) % mod) % mod; 
    }

    cout << ans << '\n';

    return 0;
}
